import { IObjRef } from "soui4/IObjRef";
import { IValueAnimator } from "soui4/IValueAnimator";
import { IWindow } from "soui4/IWindow";

/**
 * Property type constants
 */
export enum PROP_TYPE {
    UNKNOWN = 0,
    BYTE,
    SHORT,
    COLORREF,
    INT,
    FLOAT,
    LAYOUT_SIZE,
    VARIANT
}

/**
 * Interface for property values holder
 */
export interface IPropertyValuesHolder extends IObjRef {
    /** Set property name */
    SetPropertyName(name: string): void;

    /** Get property name */
    GetPropertyName(): string;

    /** Set byte values */
    SetByteValues(values: number[]): void;

    /** Set short values */
    SetShortValues(values: number[]): void;

    /** Set color reference values */
    SetColorRefValues(values: number[]): void;

    /** Set float values */
    SetFloatValues(values: number[]): void;

    /** Set int values */
    SetIntValues(values: number[]): void;


    /** Get animated value at specified fraction */
    GetAnimatedValue(fraction: number): number;

    /** Get value type */
    GetValueType(): PROP_TYPE;

    /** Get value size */
    GetValueSize(): number;

    /** Get keyframe count */
    GetKeyframeCount(): number;

    /** Set key frame weights */
    SetKeyFrameWeights(weights: number[]): boolean;

    /** Get key frame weights */
    GetKeyFrameWeights(weights: number[]): boolean;
}

export interface IPropertyAnimator extends IValueAnimator {
    /** Get animation target */
    GetTarget(): IWindow;
    /** Set animation target */
    SetTarget(target: IWindow): void;
    /** Set property values holder */
    SetPropertyValuesHolder(holder: IPropertyValuesHolder): void;
    /** Set multiple property values holders */
    SetPropertyValuesHolders(holders: IPropertyValuesHolder[]): void;
    /** Get property values holder by name */
    GetPropertyValuesHolderByName(propertyName: string): IPropertyValuesHolder;
    /** Get property values holder by index */
    GetPropertyValuesHolderByIndex(index: number): IPropertyValuesHolder;
    /** Get property values holder count */
    GetPropertyValuesHolderCount(): number;
    /** Copy from another property animator */
    CopyFrom(ani: IPropertyAnimator): boolean;
    /** Get animated fraction */
    GetAnimatedFraction(): number;
}

